import { readFile, writeFile } from 'node:fs/promises';
import { decode } from './index.mjs';

const [inputPath, outputPath, rateValue = '24000'] = process.argv.slice(2);
if (!inputPath || !outputPath) throw new Error('input and output paths are required');
const sampleRate = Number(rateValue);
const source = await readFile(inputPath);
const result = await decode(source, sampleRate);
const pcm = Buffer.from(result.data);
const header = Buffer.alloc(44);
header.write('RIFF', 0);
header.writeUInt32LE(36 + pcm.length, 4);
header.write('WAVEfmt ', 8);
header.writeUInt32LE(16, 16);
header.writeUInt16LE(1, 20);
header.writeUInt16LE(1, 22);
header.writeUInt32LE(sampleRate, 24);
header.writeUInt32LE(sampleRate * 2, 28);
header.writeUInt16LE(2, 32);
header.writeUInt16LE(16, 34);
header.write('data', 36);
header.writeUInt32LE(pcm.length, 40);
await writeFile(outputPath, Buffer.concat([header, pcm]));
